// Bite alerts for Fish Bite Forecast.
//  GET  ?vapid           -> { key }  public VAPID key (generated once, stored in forecast_secrets)
//  POST ?test  (user JWT) -> sends a test notification to the caller's devices
//  POST ?run   (x-cron-key header) -> scores every enabled alert rule and sends pushes
// The scoring uses the same engine as the app (core.js is generated by build.js).
import { createClient } from "npm:@supabase/supabase-js@2";
import webpush from "npm:web-push@3.6.7";
import { Engine, SPECIES, speciesFits, regionOf, TIDE_CACHE } from "./core.js";

const URL_ = Deno.env.get("SUPABASE_URL")!, SRK = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
const db = createClient(URL_, SRK, { auth: { persistSession: false } });
const CORS = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "authorization, apikey, content-type, x-client-info", "Access-Control-Allow-Methods": "GET, POST, OPTIONS" };
const J = (o: unknown, s = 200) => new Response(JSON.stringify(o), { status: s, headers: { ...CORS, "Content-Type": "application/json" } });
const UA = { "User-Agent": "(fishforecast.net, alerts)", Accept: "application/geo+json" };
const SPMAP: Record<string, any> = Object.fromEntries(SPECIES.map((s: any) => [s.id, s]));

const b64u = (buf: ArrayBuffer) => btoa(String.fromCharCode(...new Uint8Array(buf))).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
async function secret(k: string) { const { data } = await db.from("forecast_secrets").select("v").eq("k", k).maybeSingle(); return data?.v as string | undefined; }
async function vapid() {
  let pub = await secret("vapid_public"), priv = await secret("vapid_private");
  if (!pub || !priv) {
    const kp = await crypto.subtle.generateKey({ name: "ECDSA", namedCurve: "P-256" }, true, ["sign", "verify"]);
    pub = b64u(await crypto.subtle.exportKey("raw", kp.publicKey));
    priv = (await crypto.subtle.exportKey("jwk", kp.privateKey)).d!;
    await db.from("forecast_secrets").upsert([{ k: "vapid_public", v: pub }, { k: "vapid_private", v: priv }]);
  }
  webpush.setVapidDetails("mailto:support@flytyingrecipes.org", pub, priv);
  return pub;
}
async function pushTo(userId: string, payload: Record<string, unknown>) {
  const { data: subs } = await db.from("forecast_push_subs").select("id, endpoint, p256dh, auth").eq("user_id", userId);
  let sent = 0;
  for (const s of subs || []) {
    try { await webpush.sendNotification({ endpoint: s.endpoint, keys: { p256dh: s.p256dh, auth: s.auth } }, JSON.stringify(payload), { TTL: 6 * 3600 }); sent++; }
    catch (e: any) { if (e?.statusCode === 404 || e?.statusCode === 410) await db.from("forecast_push_subs").delete().eq("id", s.id); else console.log("push failed", e?.statusCode, e?.body || String(e)); }
  }
  return sent;
}

// ---- data for scoring (cached for one run) ----
const cache = new Map<string, Promise<any>>();
const once = (k: string, f: () => Promise<any>) => { if (!cache.has(k)) cache.set(k, f().catch(() => null)); return cache.get(k)!; };
const getJSON = async (u: string, h: Record<string, string> = {}) => { const r = await fetch(u, { headers: h }); if (!r.ok) throw new Error(u + " " + r.status); return r.json(); };
function weather(lat: number, lng: number) {
  return once(`wx${lat.toFixed(2)},${lng.toFixed(2)}`, async () => {
    const base = `latitude=${lat}&longitude=${lng}&timezone=auto`;
    const w = await getJSON(`https://api.open-meteo.com/v1/forecast?${base}&hourly=pressure_msl,wind_speed_10m,cloud_cover,precipitation_probability,temperature_2m&wind_speed_unit=mph&temperature_unit=fahrenheit&past_days=7&forecast_days=6`);
    let sst = null; try { sst = (await getJSON(`https://marine-api.open-meteo.com/v1/marine?${base}&hourly=sea_surface_temperature&temperature_unit=fahrenheit&past_days=1&forecast_days=6`)).hourly; } catch (_) { /* inland */ }
    return { h: w.hourly, off: w.utc_offset_seconds as number, tz: w.timezone as string, sst };
  });
}
function cond(wx: any, water: string, key: string, prev: string, t0: number) {
  const H = wx.h, avg = (a: number[]) => a.length ? a.reduce((x, y) => x + y, 0) / a.length : null;
  const pick = (arr: number[], day: string) => { const o: number[] = []; H.time.forEach((t: string, i: number) => { const hr = +t.slice(11, 13); if (t.slice(0, 10) === day && hr >= 6 && hr <= 18 && arr[i] != null) o.push(arr[i]); }); return o; };
  const pT = avg(pick(H.pressure_msl, key)), pY = avg(pick(H.pressure_msl, prev));
  const wind = avg(pick(H.wind_speed_10m, key)), cloud = avg(pick(H.cloud_cover, key)) ?? 50, rain = Math.max(0, ...pick(H.precipitation_probability, key));
  const dp = pT == null || pY == null ? 0 : pT - pY;
  const pressure = dp < -5 ? "ff" : dp < -2 ? "f" : (dp > 4 && cloud < 35) ? "pf" : dp > 1.5 ? "r" : "s";
  const sky = rain >= 60 ? "rain" : cloud < 25 ? "sun" : cloud < 70 ? "partly" : "overcast";
  let wtemp: number | null = null;
  if (!["fresh", "greatlakes"].includes(water) && wx.sst?.sea_surface_temperature) { const v: number[] = []; wx.sst.time.forEach((t: string, i: number) => { if (t.slice(0, 10) === key && wx.sst.sea_surface_temperature[i] != null) v.push(wx.sst.sea_surface_temperature[i]); }); if (v.length) wtemp = Math.round(avg(v)!); }
  if (wtemp == null) { const v: number[] = []; H.time.forEach((t: string, i: number) => { const d = Date.parse(t + ":00Z") - wx.off * 1000; if (d < t0 + 864e5 && d >= t0 - 7 * 864e5 && H.temperature_2m[i] != null) v.push(H.temperature_2m[i]); }); if (v.length) wtemp = Math.round(Math.max(34, Math.min(90, avg(v)! * .9 + 6))); }
  return { pressure, wind: wind == null ? 10 : Math.round(wind), sky, clarity: "stained", wtemp: wtemp ?? "" };
}
async function tides(station: string) {
  return once("tide" + station, async () => {
    const d = new Date(Date.now() - 864e5), ymd = d.toISOString().slice(0, 10).replace(/-/g, "");
    const j = await getJSON(`https://api.tidesandcurrents.noaa.gov/api/prod/datagetter?product=predictions&station=${station}&begin_date=${ymd}&range=168&datum=MLLW&units=english&time_zone=gmt&interval=hilo&format=json&application=fishforecast.net`);
    TIDE_CACHE[station] = (j.predictions || []).map((p: any) => ({ t: Date.parse(p.t.replace(" ", "T") + ":00Z"), h: +p.v, type: p.type === "H" ? "H" : "L" }));
    return TIDE_CACHE[station];
  });
}
function marineAlerts(lat: number, lng: number) {
  return once(`ma${lat.toFixed(2)},${lng.toFixed(2)}`, async () => {
    const z = await getJSON(`https://api.weather.gov/zones?type=marine&point=${lat.toFixed(4)},${lng.toFixed(4)}`, UA);
    const ids = (z.features || []).map((f: any) => f.properties.id);
    const out: any[] = [];
    for (const id of ids.slice(0, 2)) { const a = await getJSON(`https://api.weather.gov/alerts/active?zone=${id}`, UA); out.push(...(a.features || []).map((f: any) => f.properties)); }
    return out;
  });
}

const fmtT = (t: number, off: number) => { const d = new Date(t + off * 1000); let h = d.getUTCHours(); const m = d.getUTCMinutes(), ap = h >= 12 ? "PM" : "AM"; h = h % 12 || 12; return `${h}:${String(m).padStart(2, "0")} ${ap}`; };
const DOW = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

async function runRule(rule: any) {
  const sp = rule.spot, out: any[] = [];
  if (!sp || sp.lat == null) return out;
  const wx = await weather(sp.lat, sp.lng); if (!wx) return out;
  if (sp.station?.id) await tides(sp.station.id);
  const spot = { ...sp, tide: undefined }; // server uses NOAA station tides only
  const now = Date.now(), localNow = new Date(now + wx.off * 1000), hourNow = localNow.getUTCHours();
  const mid0 = Date.UTC(localNow.getUTCFullYear(), localNow.getUTCMonth(), localNow.getUTCDate()) - wx.off * 1000;
  const sent = { ...(rule.sent || {}) };
  for (let k = hourNow < 10 ? 0 : 1; k <= 3; k++) {
    const t0 = mid0 + k * 864e5, ld = new Date(t0 + wx.off * 1000 + 43200e3), dow = ld.getUTCDay();
    if (rule.days === "weekend" && dow !== 0 && dow !== 6) continue;
    const key = ld.toISOString().slice(0, 10), prev = new Date(t0 + wx.off * 1000 - 43200e3).toISOString().slice(0, 10);
    if (sent["bite:" + key]) continue;
    const day = Engine.buildDay(t0, spot, { lat: sp.lat, lng: sp.lng });
    const c = cond(wx, sp.water, key, prev, t0);
    const pool = rule.species && rule.species !== "auto" ? [SPMAP[rule.species]].filter(Boolean) : SPECIES.filter((s: any) => speciesFits(s, spot));
    const res = pool.map((s: any) => Engine.scoreSpecies(day, s, c, { fly: !!rule.fly, region: regionOf(sp.lat, sp.lng, sp.water) })).sort((a: any, b: any) => b.day - a.day);
    const best = res[0]; if (!best || best.day < rule.min_score) continue;
    const w = Engine.windows(best, day, 1)[0];
    const when = k === 0 ? "today" : k === 1 ? "tomorrow" : DOW[dow];
    out.push({ kind: "bite", score: best.day, key: "bite:" + key, title: `🎣 ${best.sp.name} ${Math.round(best.day)} ${when} — ${sp.name}`, body: `Best ${fmtT(w ? w.a : best.bestStart, wx.off)}–${fmtT(w ? w.b : best.bestEnd, wx.off)}${w && w.why?.length ? " · " + w.why.slice(0, 2).join(" · ") : ""}`, url: `./#forecast`, spot: sp.id, date: key });
  }
  // one bite alert at a time: the best upcoming day, and not within 20 hours of the last one
  const bites = out.filter(x => x.kind === "bite").sort((a, b) => b.score - a.score);
  out.length = 0;
  if (bites.length && !(sent.lastBite && now - sent.lastBite < 20 * 3600e3)) out.push(bites[0]);
  if (rule.sca && sp.water !== "fresh") {
    const al = (await marineAlerts(sp.lat, sp.lng)) || [];
    for (const a of al) {
      if (!/small craft|gale|storm|hazardous seas|special marine|hurricane|tropical/i.test(a.event || "")) continue;
      const key = "sca:" + (a.id || a.event + a.onset); if (sent[key]) continue;
      out.push({ kind: "sca", key, title: `⚠️ ${a.event} — ${sp.name}`, body: (a.headline || "").slice(0, 160), url: "./#marine", spot: sp.id });
    }
  }
  return out;
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: CORS });
  const u = new URL(req.url);
  try {
    if (u.searchParams.has("vapid")) return J({ key: await vapid() });
    if (u.searchParams.has("test")) {
      const tok = (req.headers.get("authorization") || "").replace(/^Bearer /i, "");
      const { data } = await db.auth.getUser(tok); if (!data?.user) return J({ error: "sign in first" }, 401);
      await vapid();
      const n = await pushTo(data.user.id, { title: "🎣 Fish Bite Forecast", body: "Bite alerts are on for this device.", url: "./#forecast", tag: "test" });
      return J({ sent: n });
    }
    if (u.searchParams.has("run")) {
      if (!req.headers.get("x-cron-key") || req.headers.get("x-cron-key") !== await secret("cron_key")) return J({ error: "forbidden" }, 403);
      await vapid();
      const { data: rules } = await db.from("forecast_alerts").select("*").eq("enabled", true).limit(500);
      let pushes = 0; const dry = u.searchParams.has("dry"), preview: any[] = [];
      for (const r of rules || []) {
        let items: any[] = [];
        try { items = await runRule(r); } catch (e) { console.log("rule failed", r.id, String(e)); preview.push({ rule: r.id, error: String(e) }); continue; }
        if (dry) { preview.push({ rule: r.id, items }); continue; }
        if (!items.length) continue;
        const sent = { ...(r.sent || {}) };
        for (const it of items.slice(0, 3)) { pushes += await pushTo(r.user_id, { title: it.title, body: it.body, url: it.url, tag: it.key }); sent[it.key] = Date.now(); if (it.kind === "bite") sent.lastBite = Date.now(); }
        for (const k of Object.keys(sent)) if (Date.now() - sent[k] > 10 * 864e5) delete sent[k];
        await db.from("forecast_alerts").update({ sent, last_run: new Date().toISOString() }).eq("id", r.id);
      }
      return J({ rules: rules?.length || 0, pushes, ...(dry ? { preview } : {}) });
    }
    return J({ error: "unknown request" }, 400);
  } catch (e) { return J({ error: String(e) }, 500); }
});
